{"content":"#!/usr/bin/env python3
"""Audit services/ against SPEC.md and the SPEC-AMENDMENT-*.md clauses."""
import ast
import glob
import json
import os
import re
import sys

ROOT = os.environ.get(
    "AUDIT_ROOT",
    "/private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/e594541a8a73",
)
LFS_MAGIC = "version https://git-lfs.github.com/spec/v1"
DIGEST_RE = re.compile(r"^@sha256:[0-9a-f]{64}$")


def read(path):
    with open(path, "r", encoding="utf-8", errors="replace", newline="") as fh:
        return fh.read()


def lines_of(text):
    return text.replace("\r\n", "\n").replace("\r", "\n").split("\n")


def is_lfs(path):
    try:
        with open(path, "rb") as fh:
            first = fh.readline().rstrip(b"\r\n")
        return first.decode("utf-8", "replace") == LFS_MAGIC
    except OSError:
        return False


def service_files(svc):
    out = []
    for base, _dirs, files in os.walk(svc):
        for f in files:
            out.append(os.path.join(base, f))
    return sorted(out)


def load_config(svc):
    path = os.path.join(svc, "config.json")
    if not os.path.isfile(path):
        return {}
    try:
        return json.loads(read(path))
    except json.JSONDecodeError:
        return {}


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def py_files(svc):
    return sorted(glob.glob(os.path.join(svc, "src", "**", "*.py"), recursive=True))


def parse_py(path):
    try:
        return ast.parse(read(path))
    except SyntaxError:
        return None


def docker_from_images(path):
    if not os.path.isfile(path):
        return []
    out = []
    for raw in lines_of(read(path)):
        s = raw.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0].lower() != "from":
            continue
        args = parts[1:]
        while args and args[0].startswith("--"):
            args = args[1:]
        if args:
            out.append(args[0])
    return out


def docker_users(path):
    if not os.path.isfile(path):
        return []
    out = []
    for raw in lines_of(read(path)):
        s = raw.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0].lower() == "user":
            out.append(parts[1] if len(parts) > 1 else "")
    return out


def c2_violation(svc):
    path = os.path.join(svc, "src", "handlers.py")
    if not os.path.isfile(path):
        return False
    tree = parse_py(path)
    if tree is None:
        return False
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if node.name.startswith("handle_") and ast.get_docstring(node) is None:
                return True
    return False


def c3_violation(svc):
    for path in py_files(svc):
        tree = parse_py(path)
        if tree is None:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
                if node.func.id == "print":
                    return True
    return False


def c9_violation(svc):
    prefixes = ("sk_live_", "AKIA")
    for path in py_files(svc):
        tree = parse_py(path)
        if tree is None:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                if node.value.startswith(prefixes):
                    return True
            elif isinstance(node, ast.JoinedStr):
                for part in node.values:
                    if isinstance(part, ast.Constant) and isinstance(part.value, str):
                        if part.value.startswith(prefixes):
                            return True
    return False


def handler_names(svc):
    path = os.path.join(svc, "src", "handlers.py")
    if not os.path.isfile(path):
        return set()
    tree = parse_py(path)
    if tree is None:
        return set()
    return {n.name for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}


def c10_violation(svc, cfg):
    if "healthcheck" not in cfg:
        return True
    hc = cfg.get("healthcheck")
    if not isinstance(hc, str):
        return False
    seg = [p for p in hc.split("?")[0].split("/") if p]
    if not seg:
        return False
    return ("handle_" + seg[-1]) not in handler_names(svc)


def c8_violation(svc, cfg):
    path = os.path.join(svc, "CODEOWNERS")
    want = "@team-" + str(cfg.get("team", ""))
    if not os.path.isfile(path):
        return True
    for raw in lines_of(read(path)):
        s = raw.split("#", 1)[0].strip()
        if not s:
            continue
        parts = s.split()
        if parts[0] != "*":
            continue
        if want in parts[1:]:
            return False
    return True


def c12_violation(svc):
    path = os.path.join(svc, "requirements.txt")
    if not os.path.isfile(path):
        return True
    for raw in lines_of(read(path)):
        s = raw.strip()
        if not s or s.startswith("#"):
            continue
        body = re.split(r"\s+#", s, 1)[0].strip()
        body = body.split(";", 1)[0].strip()
        if not re.match(r"^[A-Za-z0-9_.\-\[\]]+\s*==\s*[A-Za-z0-9_.\-+!]+$", body):
            return True
    return False


def c15_violation(svc):
    tests = os.path.join(svc, "tests")
    return not (os.path.isdir(tests) and glob.glob(os.path.join(tests, "test_*.py")))


def audit(svc):
    if any(is_lfs(p) for p in service_files(svc)):
        return {"service": os.path.basename(svc), "status": "unverifiable", "violations": []}

    cfg = load_config(svc)
    public = cfg.get("exposure") == "public"
    v = []

    if public:
        t = cfg.get("timeout_s")
        if not (is_int(t) and t <= 30):
            v.append("C1")
    if c2_violation(svc):
        v.append("C2")
    if c3_violation(svc):
        v.append("C3")
    r = cfg.get("retries")
    if not (is_int(r) and 1 <= r <= 5):
        v.append("C4")

    images = docker_from_images(os.path.join(svc, "Dockerfile"))
    bad_image = not images
    for tok in images:
        if "@" not in tok:
            bad_image = True
            continue
        if not DIGEST_RE.match("@" + tok.split("@", 1)[1]):
            bad_image = True
    if bad_image:
        v.append("C5")

    users = docker_users(os.path.join(svc, "Dockerfile"))
    if not users or users[-1].split(":", 1)[0] in ("root", "0"):
        v.append("C6")

    readme = os.path.join(svc, "README.md")
    if not os.path.isfile(readme) or "## Runbook" not in lines_of(read(readme)):
        v.append("C7")

    if c8_violation(svc, cfg):
        v.append("C8")
    if c9_violation(svc):
        v.append("C9")
    if c10_violation(svc, cfg):
        v.append("C10")
    if cfg.get("metrics_port") == cfg.get("port"):
        v.append("C11")
    if c12_violation(svc):
        v.append("C12")
    if cfg.get("log_level") == "DEBUG":
        v.append("C13")
    if public:
        mb = cfg.get("max_body_kb")
        if not (is_int(mb) and mb <= 1024):
            v.append("C14")
    if c15_violation(svc):
        v.append("C15")
    if public:
        rl = cfg.get("rate_limit_rps")
        if not (is_int(rl) and 1 <= rl <= 10000):
            v.append("C16")

    v.sort(key=lambda x: int(x[1:]))
    return {"service": os.path.basename(svc),
            "status": "violations" if v else "compliant",
            "violations": v}


def main():
    svcs = sorted(glob.glob(os.path.join(ROOT, "services", "svc-*")))
    reports = [audit(s) for s in svcs]
    for rep in reports:
        print(rep["service"], rep["status"], ",".join(rep["violations"]) or "-")
    if "--write" in sys.argv:
        outdir = os.path.join(ROOT, "findings")
        os.makedirs(outdir, exist_ok=True)
        for rep in reports:
            with open(os.path.join(outdir, rep["service"] + ".json"), "w", encoding="utf-8") as fh:
                json.dump(rep, fh)
                fh.write("\n")
        print("wrote", len(reports), "reports")


if __name__ == "__main__":
    main()
